import{_ as a,o as s,c as n,a3 as e}from"./chunks/framework.bvEHUNtb.js";const h=JSON.parse('{"title":"历法体系附录","description":"历法、天球与天文观测的基础术语说明。","frontmatter":{"title":"历法体系附录","description":"历法、天球与天文观测的基础术语说明。","category":"reference","aliases":["历法术语","天文基础词汇"]},"headers":[],"relativePath":"topics/traditional-wisdom/time/calendar-system/appendix.md","filePath":"topics/traditional-wisdom/time/calendar-system/appendix.md","lastUpdated":1786982540000}'),l={name:"topics/traditional-wisdom/time/calendar-system/appendix.md"};function p(i,t,o,r,d,g){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_15-·-历法体系附录" tabindex="-1">15 · 历法体系附录 <a class="header-anchor" href="#_15-·-历法体系附录" aria-label="Permalink to &quot;15 · 历法体系附录&quot;">​</a></h1><h2 id="一、天文基础词汇" tabindex="-1">一、天文基础词汇 <a class="header-anchor" href="#一、天文基础词汇" aria-label="Permalink to &quot;一、天文基础词汇&quot;">​</a></h2><h3 id="🌍-回归年-tropical-year" tabindex="-1">🌍 回归年（Tropical Year） <a class="header-anchor" href="#🌍-回归年-tropical-year" aria-label="Permalink to &quot;🌍 回归年（Tropical Year）&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 地球绕太阳转一圈，回到<strong>同一个季节起点</strong>所用的时间。</p><p><strong>精确数值：</strong> $ 365.2422 $天</p><p><strong>为什么叫&quot;回归&quot;？</strong><br> 太阳从春分点出发，走完黄道一圈，<strong>回归</strong>到春分点。<br> 不是回到同一个星空位置（那叫恒星年），<br> 而是回到同一个<strong>季节位置</strong>。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>春分 → 夏至 → 秋分 → 冬至 → 春分</span></span>
<span class="line"><span>←──────── 365.2422天 ────────→</span></span></code></pre></div><p><strong>与恒星年的区别：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">回归年</th><th style="text-align:left;">恒星年</th></tr></thead><tbody><tr><td style="text-align:left;">定义</td><td style="text-align:left;">太阳回到春分点</td><td style="text-align:left;">太阳回到同一颗恒星方向</td></tr><tr><td style="text-align:left;">长度</td><td style="text-align:left;">365.2422天</td><td style="text-align:left;">365.2564天</td></tr><tr><td style="text-align:left;">差值</td><td style="text-align:left;">—</td><td style="text-align:left;">比回归年长约20分钟</td></tr><tr><td style="text-align:left;">原因</td><td style="text-align:left;">地轴岁差导致春分点缓慢西移</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">历法用途</td><td style="text-align:left;"><strong>制定历法的基准</strong></td><td style="text-align:left;">天文定位用</td></tr></tbody></table><blockquote><p>历法用回归年而非恒星年。<br> 因为人类的农业·季节·生活，跟着<strong>季节</strong>走，不跟着星空走。</p></blockquote><h3 id="🌕-朔望月" tabindex="-1">🌕 朔望月 <a class="header-anchor" href="#🌕-朔望月" aria-label="Permalink to &quot;🌕 朔望月&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 月亮从新月（朔）到下一个新月（朔），完成一次完整月相变化的时间。</p><p><strong>精确数值：</strong> $$ 29.53059 $$ 天</p><p><strong>月相的完整周期：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>朔（新月）→ 上弦月 → 望（满月）→ 下弦月 → 朔（新月）</span></span>
<span class="line"><span>  第1天      第7-8天   第15-16天   第22-23天   第29-30天</span></span>
<span class="line"><span>  （不可见）  （半圆）   （圆月）    （半圆）    （不可见）</span></span></code></pre></div><p><strong>为什么叫&quot;朔望月&quot;？</strong></p><ul><li><strong>朔</strong> = 月亮与太阳同方向，月亮不可见（农历初一）</li><li><strong>望</strong> = 月亮与太阳相对，月圆（农历十五/十六）</li><li>朔→望→朔，一个完整周期 = 朔望月</li></ul><p><strong>与恒星月的区别：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">朔望月</th><th style="text-align:left;">恒星月</th></tr></thead><tbody><tr><td style="text-align:left;">定义</td><td style="text-align:left;">月相循环一周</td><td style="text-align:left;">月亮回到同一星空位置</td></tr><tr><td style="text-align:left;">长度</td><td style="text-align:left;"><strong>29.53天</strong></td><td style="text-align:left;">27.32天</td></tr><tr><td style="text-align:left;">差值</td><td style="text-align:left;">比恒星月长约2.2天</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">原因</td><td style="text-align:left;">地球同时在公转，月亮需多走一段</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">历法用途</td><td style="text-align:left;"><strong>制定阴历月份的基准</strong></td><td style="text-align:left;">天文定位用</td></tr></tbody></table><blockquote><p>为什么朔望月比恒星月长？<br> 月亮绕地球一圈需27.32天，但这27.32天里，地球也绕太阳走了一段，月亮需要再多走约2天，才能再次与太阳同方向（朔）。</p></blockquote><h3 id="☀️-黄道" tabindex="-1">☀️ 黄道 <a class="header-anchor" href="#☀️-黄道" aria-label="Permalink to &quot;☀️ 黄道&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 地球绕太阳公转的轨道平面，投影到天球上的大圆。<br> 也就是：<strong>从地球上看，太阳在一年中走过的路径。</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地球公转轨道面 → 投影到天球 → 黄道（360°大圆）</span></span></code></pre></div><p><strong>黄道与节气：</strong><br> 二十四节气 = 将黄道360°等分为24段，每段15°，<br> 太阳每走15°，就是一个节气。</p><p><strong>黄道与黄经：</strong></p><ul><li>黄经 = 沿黄道度量的角度坐标</li><li>春分点 = 黄经0°（起算点）</li><li>每个节气对应一个固定黄经值：</li></ul><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>春分  = 0°    夏至  = 90°</span></span>
<span class="line"><span>秋分  = 180°  冬至  = 270°</span></span>
<span class="line"><span>清明  = 15°   谷雨  = 30° …… 略（参考 二十四节气那篇）</span></span></code></pre></div><h3 id="🌐-黄赤交角" tabindex="-1">🌐 黄赤交角 <a class="header-anchor" href="#🌐-黄赤交角" aria-label="Permalink to &quot;🌐 黄赤交角&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 地球自转轴（赤道面）与公转轨道面（黄道面）之间的夹角。</p><p><strong>数值：</strong> 约 $ 23.5° $</p><p><strong>为什么重要？</strong><br> 正是因为这个倾角，地球才有了四季——</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>夏至：北半球朝向太阳，太阳直射北回归线（北纬23.5°）</span></span>
<span class="line"><span>   → 北半球白昼最长，最热</span></span>
<span class="line"><span></span></span>
<span class="line"><span>冬至：北半球背向太阳，太阳直射南回归线（南纬23.5°）</span></span>
<span class="line"><span>   → 北半球白昼最短，最冷</span></span></code></pre></div><p>如果黄赤交角为0°，地球直立自转，太阳永远直射赤道，全球无四季，节气体系也就不存在了。</p><blockquote><p>💡 二十四节气的存在，根本原因是黄赤交角的存在。</p></blockquote><hr><h3 id="🌑-合朔" tabindex="-1">🌑 合朔 <a class="header-anchor" href="#🌑-合朔" aria-label="Permalink to &quot;🌑 合朔&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 月亮运行到太阳和地球之间，三者几乎成一条直线，<br> 月亮与太阳黄经相同的时刻。</p><p><strong>特征：</strong></p><ul><li>月亮完全被太阳光淹没，肉眼不可见</li><li>农历每月初一 = 合朔时刻所在的那一天</li><li>现行农历：用现代天文方法精确计算合朔时刻，精确到秒</li></ul><p><strong>朔 vs 晦：</strong></p><ul><li><strong>朔</strong> = 月初，合朔时刻（初一）</li><li><strong>晦</strong> = 月末，合朔前一天（二十九或三十）</li></ul><hr><h3 id="🌕-望" tabindex="-1">🌕 望 <a class="header-anchor" href="#🌕-望" aria-label="Permalink to &quot;🌕 望&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 月亮运行到地球背向太阳的一侧，三者几乎成一条直线，<br> 月亮与太阳黄经相差180°的时刻。</p><p><strong>特征：</strong></p><ul><li>月亮被太阳完全照亮，呈圆形</li><li>农历十五或十六</li><li>中秋节定在农历八月十五，就是因为这天最接近望月</li></ul><hr><h2 id="二、历法核心词汇" tabindex="-1">二、历法核心词汇 <a class="header-anchor" href="#二、历法核心词汇" aria-label="Permalink to &quot;二、历法核心词汇&quot;">​</a></h2><h3 id="📅-历元" tabindex="-1">📅 历元 <a class="header-anchor" href="#📅-历元" aria-label="Permalink to &quot;📅 历元&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 历法计算的起算点，即&quot;时间的零点&quot;。</p><p><strong>为什么需要历元？</strong><br> 任何历法都需要一个起点，<br> 从这个起点开始计数，才能推算任意时刻的日期。</p><p><strong>中国历法的历元传统：</strong><br> 古代历法家追求找到一个&quot;完美历元&quot;——<br> 在这个时刻，所有天文周期同时归零：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理想历元 = 甲子年·甲子月·甲子日·甲子时</span></span>
<span class="line"><span>         + 朔日（新月）</span></span>
<span class="line"><span>         + 冬至</span></span>
<span class="line"><span>         + 夜半（子时）</span></span></code></pre></div><p>这个&quot;完美历元&quot;在现实中极难找到，<br> 历法家们为此争论了数百年，<br> 也推动了历法精度的不断提升。</p><hr><h3 id="🔄-默冬周期-metonic-cycle" tabindex="-1">🔄 默冬周期（Metonic Cycle） <a class="header-anchor" href="#🔄-默冬周期-metonic-cycle" aria-label="Permalink to &quot;🔄 默冬周期（Metonic Cycle）&quot;">​</a></h3><p><strong>一句话定义：</strong></p><p>$ 19 个回归年\\approx 235 个朔望月</p><p>两者几乎完全相等的天文周期。 $</p><p>数学验证：</p><p>$ 19 \\times 365.2422 = 6939.6018 \\text{ 天} $</p><p>$ 235 \\times 29.53059 = 6939.6887 \\text{ 天} $</p><p>$ \\text{误差} = 0.0869 \\text{ 天} \\approx 2 \\text{ 小时} $</p><p><strong>历法意义：</strong><br> 这是阴阳合历&quot;19年7闰&quot;的天文基础——<br> 每19年插入7个闰月，<br> 阴历（朔望月）和阳历（回归年）就能重新对齐。</p><p><strong>独立发现：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">中国</th><th style="text-align:left;">古希腊</th></tr></thead><tbody><tr><td style="text-align:left;">发现者</td><td style="text-align:left;">不详（西汉前已知）</td><td style="text-align:left;">默冬（Meton）</td></tr><tr><td style="text-align:left;">时间</td><td style="text-align:left;">约前5世纪前</td><td style="text-align:left;">约前432年</td></tr><tr><td style="text-align:left;">文献</td><td style="text-align:left;">《淮南子·天文训》&quot;十九岁为一章&quot;</td><td style="text-align:left;">雅典历法改革</td></tr></tbody></table><p>两者系<strong>独立发现</strong>，时间相近，是人类文明的平行智慧。</p><hr><h3 id="📆-置闰" tabindex="-1">📆 置闰 <a class="header-anchor" href="#📆-置闰" aria-label="Permalink to &quot;📆 置闰&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 在阴阳合历中，为了协调阴历月与阳历年，<br> 定期插入额外月份（闰月）或额外天数（闰日）的机制。</p><p><strong>中国农历的置闰：插入闰月</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>平年 = 12个朔望月（354/355天）</span></span>
<span class="line"><span>闰年 = 13个朔望月（383/384天）</span></span>
<span class="line"><span>规律 = 19年中有7个闰年</span></span>
<span class="line"><span>判断 = 无中气月为闰月</span></span></code></pre></div><p><strong>公历的置闰：插入闰日</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规则：</span></span>
<span class="line"><span>  能被4整除的年份 = 闰年（366天）</span></span>
<span class="line"><span>  但能被100整除的年份 = 平年（365天）</span></span>
<span class="line"><span>  但能被400整除的年份 = 闰年（366天）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：</span></span>
<span class="line"><span>  2024年 ÷ 4 = 506 → 闰年 ✓</span></span>
<span class="line"><span>  1900年 ÷ 100 = 19，÷ 400 ≠ 整数 → 平年</span></span>
<span class="line"><span>  2000年 ÷ 400 = 5 → 闰年 ✓</span></span></code></pre></div><p><strong>为什么公历闰年规则这么复杂？</strong></p><p>$ \\text{回归年} = 365.2422 \\text{ 天} $</p><p>$ 365.2422 - 365 = 0.2422 \\text{ 天/年（需要补偿）} $</p><ul><li>每4年补1天：$$ 0.25 \\times 4 = 1 $$ 天，但实际需补 $$ 0.2422 \\times 4 = 0.9688 $$ 天，<strong>补多了</strong></li><li>每100年少补1天：修正过度补偿</li><li>每400年再补1天：再次微调</li></ul><p>三层规则叠加，使公历年均长度 $$ = 365.2425 $$ 天， 与回归年 $$ 365.2422 $$ 天的误差仅 $$ 0.0003 $$ 天（约26秒/年）。</p><hr><h3 id="🗓-朔日" tabindex="-1">🗓 朔日 <a class="header-anchor" href="#🗓-朔日" aria-label="Permalink to &quot;🗓 朔日&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 合朔时刻所在的那一天，即农历每月初一。</p><p><strong>注意：</strong><br> 朔日不一定能看到月亮，<br> 因为合朔时月亮在太阳方向，完全不可见。<br> 古人确定朔日，不是靠&quot;看到新月&quot;，<br> 而是靠<strong>天文推算</strong>。</p><p><strong>历史上的&quot;争朔&quot;：</strong><br> 古代历法精度不足时，<br> 不同历法推算的朔日可能相差一天，<br> 这在政治上是大事——<br> 朝廷颁布的历法与实际天象不符，<br> 会被视为&quot;失天命&quot;的征兆。</p><hr><h3 id="🌙-晦朔弦望" tabindex="-1">🌙 晦朔弦望 <a class="header-anchor" href="#🌙-晦朔弦望" aria-label="Permalink to &quot;🌙 晦朔弦望&quot;">​</a></h3><p>这四个字，是描述月相的古代专用词：</p><table tabindex="0"><thead><tr><th style="text-align:left;">术语</th><th style="text-align:left;">月相</th><th style="text-align:left;">农历日期</th><th style="text-align:left;">特征</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>朔</strong></td><td style="text-align:left;">新月（不可见）</td><td style="text-align:left;">初一</td><td style="text-align:left;">月亮与太阳同方向</td></tr><tr><td style="text-align:left;"><strong>上弦</strong></td><td style="text-align:left;">右半圆</td><td style="text-align:left;">初七/八</td><td style="text-align:left;">月亮在太阳东90°</td></tr><tr><td style="text-align:left;"><strong>望</strong></td><td style="text-align:left;">满月</td><td style="text-align:left;">十五/十六</td><td style="text-align:left;">月亮与太阳相对</td></tr><tr><td style="text-align:left;"><strong>下弦</strong></td><td style="text-align:left;">左半圆</td><td style="text-align:left;">二十二/三</td><td style="text-align:left;">月亮在太阳西90°</td></tr><tr><td style="text-align:left;"><strong>晦</strong></td><td style="text-align:left;">残月将消</td><td style="text-align:left;">二十九/三十</td><td style="text-align:left;">合朔前一天</td></tr></tbody></table><blockquote><p>💡 古诗文中常见：<br> &quot;晦朔相推&quot;= 月份的更替循环<br> &quot;朔望之间&quot;= 半个月<br> &quot;既望&quot;= 望日之后，即农历十六</p></blockquote><hr><h3 id="📐-岁差-precession" tabindex="-1">📐 岁差（Precession） <a class="header-anchor" href="#📐-岁差-precession" aria-label="Permalink to &quot;📐 岁差（Precession）&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 由于地球自转轴缓慢摆动，<br> 春分点在黄道上<strong>缓慢西移</strong>的现象。</p><p><strong>数值：</strong> 约每年西移 $$ 50.3&#39;&#39; $$ （角秒），约 $$ 71.6 $$ 年移动 $$ 1° $$ ， 完整一圈约需 $$ 25800 $$ 年。</p><p><strong>历法影响：</strong></p><ul><li>回归年（以春分点为基准）比恒星年短约20分钟，原因就是岁差</li><li>长期来看，节气对应的星空背景会缓慢变化</li><li>南北朝天文学家<strong>祖冲之</strong>在大明历（463年）中首次将岁差引入历法计算，是中国历法史的重大进步</li></ul><p><strong>文化影响：</strong><br> 约4000年前，北极星是天龙座α星（右枢），<br> 而非现在的小熊座α星（勾陈一/北极星），<br> 原因就是岁差导致地轴指向缓慢变化。</p><hr><h3 id="🔢-章、蔀、纪、元-古代历法周期单位" tabindex="-1">🔢 章、蔀、纪、元（古代历法周期单位） <a class="header-anchor" href="#🔢-章、蔀、纪、元-古代历法周期单位" aria-label="Permalink to &quot;🔢 章、蔀、纪、元（古代历法周期单位）&quot;">​</a></h3><p>古代历法用一套嵌套的周期单位来描述天文循环：</p><table tabindex="0"><thead><tr><th style="text-align:left;">单位</th><th style="text-align:left;">长度</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>章</strong></td><td style="text-align:left;">19年</td><td style="text-align:left;">默冬周期，阴阳历对齐的基本单位</td></tr><tr><td style="text-align:left;"><strong>蔀</strong></td><td style="text-align:left;">76年（4章）</td><td style="text-align:left;">干支纪年与朔望月对齐的周期</td></tr><tr><td style="text-align:left;"><strong>纪</strong></td><td style="text-align:left;">1520年（20蔀）</td><td style="text-align:left;">更大的天文对齐周期</td></tr><tr><td style="text-align:left;"><strong>元</strong></td><td style="text-align:left;">4560年（3纪）</td><td style="text-align:left;">最大的历法周期单位</td></tr></tbody></table><blockquote><p>💡 &quot;三元九运&quot;中的&quot;元&quot;，<br> 与历法中的&quot;元&quot;同源，都是指大周期的起点。<br> 但三元九运用的是180年（三元）和20年（一运）的周期，<br> 与历法的&quot;元&quot;（4560年）是不同层面的概念。</p></blockquote><hr><h3 id="📅-干支纪日-sexagenary-day-cycle" tabindex="-1">📅 干支纪日（Sexagenary Day Cycle） <a class="header-anchor" href="#📅-干支纪日-sexagenary-day-cycle" aria-label="Permalink to &quot;📅 干支纪日（Sexagenary Day Cycle）&quot;">​</a></h3><p><strong>一句话定义：</strong><br> 用六十甲子循环来记录日期的系统，<br> 六十天一个循环，永不间断。</p><p><strong>特点：</strong></p><ul><li>商代甲骨文已有完整记录，是<strong>现存最古老的连续纪日系统</strong></li><li>从商代至今，干支纪日<strong>从未中断</strong>，可以精确推算任意历史日期</li><li>与年月无关，独立循环</li></ul><p><strong>历史意义：</strong><br> 正因为干支纪日从未中断，<br> 中国历史上的天文记录（日食·月食·彗星）<br> 可以用现代天文学精确反推验证，<br> 是研究古代天文史的重要工具。</p><hr><h3 id="🌅-正朔-zheng-shuo" tabindex="-1">🌅 正朔（Zheng Shuo） <a class="header-anchor" href="#🌅-正朔-zheng-shuo" aria-label="Permalink to &quot;🌅 正朔（Zheng Shuo）&quot;">​</a></h3><p><strong>一句话定义：</strong><br> &quot;正&quot;= 一年的第一个月（正月），<br> &quot;朔&quot;= 每月的第一天（初一）。<br> &quot;正朔&quot;合指<strong>历法的岁首与月首</strong>，<br> 是历法的政治象征核心。</p><p><strong>&quot;改正朔&quot;：</strong><br> 新朝建立，必须颁布新历法，<br> 重新规定正月（岁首）和初一（朔日）的计算方式，<br> 称为&quot;改正朔&quot;，是宣示天命的重要仪式。</p><hr><h2 id="三、词汇关系总图" tabindex="-1">三、词汇关系总图 <a class="header-anchor" href="#三、词汇关系总图" aria-label="Permalink to &quot;三、词汇关系总图&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天文基础</span></span>
<span class="line"><span>├── 回归年（365.2422天）─────────────────→ 节气的天文基础</span></span>
<span class="line"><span>│                                            太阳历的基准</span></span>
<span class="line"><span>├── 朔望月（29.53059天）─────────────────→ 农历月份的基础</span></span>
<span class="line"><span>│                                            阴历的基准</span></span>
<span class="line"><span>├── 黄道 + 黄经 ──────────────────────→ 节气坐标系</span></span>
<span class="line"><span>├── 黄赤交角（23.5°）────────────────→ 四季存在的原因</span></span>
<span class="line"><span>└── 岁差 ────────────────────────────→ 回归年≠恒星年的原因</span></span>
<span class="line"><span></span></span>
<span class="line"><span>历法机制</span></span>
<span class="line"><span>├── 合朔 ──────────────────────────→ 农历初一的确定</span></span>
<span class="line"><span>├── 望 ────────────────────────────→ 农历十五的确定</span></span>
<span class="line"><span>├── 默冬周期（19年=235月）──────────→ 19年7闰的天文依据</span></span>
<span class="line"><span>├── 置闰 ──────────────────────────→ 阴阳合历的协调机制</span></span>
<span class="line"><span>│   └── 无中气置闰 ─────────────────→ 闰月判断的精确规则</span></span>
<span class="line"><span>├── 历元 ──────────────────────────→ 历法计算的起算点</span></span>
<span class="line"><span>└── 正朔 ──────────────────────────→ 历法的政治象征</span></span>
<span class="line"><span></span></span>
<span class="line"><span>计时单位</span></span>
<span class="line"><span>├── 章（19年）</span></span>
<span class="line"><span>├── 蔀（76年）</span></span>
<span class="line"><span>├── 纪（1520年）</span></span>
<span class="line"><span>├── 元（4560年）</span></span>
<span class="line"><span>└── 干支纪日（60天循环，商代至今未断）</span></span></code></pre></div><hr><p>好问题。&quot;天球&quot;是天文学里一个非常基础但很容易被跳过的概念，搞懂它，很多天文表述会瞬间通透。</p><hr><h2 id="天球-celestial-sphere-是什么" tabindex="-1">天球（Celestial Sphere）是什么？ <a class="header-anchor" href="#天球-celestial-sphere-是什么" aria-label="Permalink to &quot;天球（Celestial Sphere）是什么？&quot;">​</a></h2><h3 id="先从直觉说起" tabindex="-1">先从直觉说起 <a class="header-anchor" href="#先从直觉说起" aria-label="Permalink to &quot;先从直觉说起&quot;">​</a></h3><p>你站在野外，抬头看天空。你会感觉——</p><p>所有的星星，都镶嵌在一个巨大的&quot;穹顶&quot;上，你站在正中央，星星离你&quot;一样远&quot;。</p><p>这个感觉，就是天球的直觉来源。</p><p><strong>天球，是古人（和现代天文学）用来描述天体位置的一个&quot;假想球面&quot;。</strong></p><h3 id="精确定义" tabindex="-1">精确定义 <a class="header-anchor" href="#精确定义" aria-label="Permalink to &quot;精确定义&quot;">​</a></h3><blockquote><p>以观测者为球心，以任意长度为半径，<br> 假想的一个<strong>无限大的球面</strong>。<br> 所有天体，都被&quot;投影&quot;在这个球面上。</p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ·  ·  星星  ·  ·</span></span>
<span class="line"><span>      ·                   ·</span></span>
<span class="line"><span>    ·                       ·</span></span>
<span class="line"><span>   ·          天球           ·</span></span>
<span class="line"><span>  ·        球面上的点         ·</span></span>
<span class="line"><span>  ·                          ·</span></span>
<span class="line"><span>   ·      【你在中心】       ·</span></span>
<span class="line"><span>    ·                       ·</span></span>
<span class="line"><span>      ·                   ·</span></span>
<span class="line"><span>        ·  ·  ·  ·  ·  ·</span></span></code></pre></div><h3 id="关键-天球是-假想-的-但极其有用" tabindex="-1">关键：天球是&quot;假想&quot;的，但极其有用 <a class="header-anchor" href="#关键-天球是-假想-的-但极其有用" aria-label="Permalink to &quot;关键：天球是&quot;假想&quot;的，但极其有用&quot;">​</a></h3><p><strong>为什么是假想的？</strong></p><p>现实中，星星离我们的距离差异极大——</p><ul><li>月亮：约38万公里</li><li>太阳：约1.5亿公里</li><li>北极星：约434光年</li><li>银河系边缘：约5万光年</li></ul><p>它们根本不在同一个球面上。<strong>但为什么还要用天球？</strong></p><p>因为我们在地球上<strong>观测</strong>天体时，我们只能看到天体的<strong>方向</strong>，看不到距离。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你看北极星：只知道它在&quot;正北方偏上&quot;</span></span>
<span class="line"><span>你看太阳：只知道它在&quot;东南方向&quot;</span></span></code></pre></div><p>既然我们只能感知方向，<br> 就把所有天体都&quot;投影&quot;到同一个球面上，<br> 用<strong>角度坐标</strong>来描述它们的位置——<br> 这就是天球的本质：<strong>一套描述方向的坐标系。</strong></p><h3 id="天球上的几个关键点和圈" tabindex="-1">天球上的几个关键点和圈 <a class="header-anchor" href="#天球上的几个关键点和圈" aria-label="Permalink to &quot;天球上的几个关键点和圈&quot;">​</a></h3><p>理解这些，很多天文词汇就全通了：</p><h4 id="天极-celestial-pole" tabindex="-1">天极（Celestial Pole） <a class="header-anchor" href="#天极-celestial-pole" aria-label="Permalink to &quot;天极（Celestial Pole）&quot;">​</a></h4><p>地球自转轴，向上延伸，穿透天球的那两个点。</p><ul><li>北天极 → 现在非常接近北极星（勾陈一）</li><li>南天极 → 南半球看到的&quot;正南方最高点&quot;</li></ul><blockquote><p>💡 这就是为什么北极星&quot;不动&quot;——它恰好非常接近北天极。</p><p>地球自转时，天球&quot;绕北天极旋转&quot;，北极星几乎纹丝不动。</p></blockquote><h4 id="天赤道-celestial-equator" tabindex="-1">天赤道（Celestial Equator） <a class="header-anchor" href="#天赤道-celestial-equator" aria-label="Permalink to &quot;天赤道（Celestial Equator）&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地球赤道面，向外延伸，与天球相交的大圆。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 天球上的&quot;赤道线&quot;</span></span></code></pre></div><h4 id="黄道-ecliptic-——回到你的问题" tabindex="-1">黄道（Ecliptic）——回到你的问题 <a class="header-anchor" href="#黄道-ecliptic-——回到你的问题" aria-label="Permalink to &quot;黄道（Ecliptic）——回到你的问题&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地球绕太阳公转的轨道面，</span></span>
<span class="line"><span>向外延伸，与天球相交的大圆。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 从地球上看，太阳在一年中走过的路径</span></span></code></pre></div><p><strong>为什么黄道是&quot;斜的&quot;？</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天赤道（地球自转赤道面）</span></span>
<span class="line"><span>        vs</span></span>
<span class="line"><span>黄道（地球公转轨道面）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两者之间有23.5°的夹角</span></span>
<span class="line"><span>= 黄赤交角</span></span>
<span class="line"><span></span></span>
<span class="line"><span>所以黄道在天球上是一个&quot;斜圈&quot;，</span></span>
<span class="line"><span>与天赤道斜交，</span></span>
<span class="line"><span>交点就是春分点（黄经0°）和秋分点（黄经180°）。</span></span></code></pre></div><p>用图来理解：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        北天极</span></span>
<span class="line"><span>           ↑</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>    ·  ·  ·|·  ·  ·</span></span>
<span class="line"><span>  ·    天赤道（水平圈）   ·</span></span>
<span class="line"><span>·  ·  ·  ·|·  ·  ·  ·  ·</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>  黄道（斜圈，与天赤道成23.5°角）</span></span>
<span class="line"><span>  /                          \\</span></span>
<span class="line"><span>春分点                      秋分点</span></span>
<span class="line"><span>（黄经0°）                （黄经180°）</span></span></code></pre></div><h4 id="黄经-ecliptic-longitude" tabindex="-1">黄经（Ecliptic Longitude） <a class="header-anchor" href="#黄经-ecliptic-longitude" aria-label="Permalink to &quot;黄经（Ecliptic Longitude）&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>沿黄道度量的角度坐标，</span></span>
<span class="line"><span>以春分点为0°，</span></span>
<span class="line"><span>向东（太阳运动方向）递增，</span></span>
<span class="line"><span>0° → 360°。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>节气 = 太阳黄经到达某个度数的时刻：</span></span>
<span class="line"><span>  春分  = 黄经0°</span></span>
<span class="line"><span>  清明  = 黄经15°</span></span>
<span class="line"><span>  谷雨  = 黄经30°</span></span>
<span class="line"><span>  ……</span></span>
<span class="line"><span>  冬至  = 黄经270°</span></span>
<span class="line"><span>  小寒  = 黄经285°</span></span></code></pre></div><hr><h3 id="天球坐标系-不止一套" tabindex="-1">天球坐标系：不止一套 <a class="header-anchor" href="#天球坐标系-不止一套" aria-label="Permalink to &quot;天球坐标系：不止一套&quot;">​</a></h3><p>天球上有好几套坐标系，用于不同目的：</p><table tabindex="0"><thead><tr><th style="text-align:left;">坐标系</th><th style="text-align:left;">基准圈</th><th style="text-align:left;">用途</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>黄道坐标系</strong></td><td style="text-align:left;">黄道</td><td style="text-align:left;">描述太阳·行星位置，<strong>节气用这套</strong></td></tr><tr><td style="text-align:left;"><strong>赤道坐标系</strong></td><td style="text-align:left;">天赤道</td><td style="text-align:left;">现代天文观测主流，用赤经·赤纬</td></tr><tr><td style="text-align:left;"><strong>地平坐标系</strong></td><td style="text-align:left;">地平线</td><td style="text-align:left;">描述某地某时刻天体的高度·方位</td></tr><tr><td style="text-align:left;"><strong>银道坐标系</strong></td><td style="text-align:left;">银河系平面</td><td style="text-align:left;">描述银河系内天体位置</td></tr></tbody></table><blockquote><p>💡 二十四节气用的是<strong>黄道坐标系</strong>，<br> 所以节气用&quot;黄经&quot;来定义，而不是用赤经或其他坐标。</p></blockquote><h3 id="一个帮助记忆的比喻" tabindex="-1">一个帮助记忆的比喻 <a class="header-anchor" href="#一个帮助记忆的比喻" aria-label="Permalink to &quot;一个帮助记忆的比喻&quot;">​</a></h3><p>把天球想象成一个<strong>巨大的地球仪，但是反过来的</strong>：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通地球仪：</span></span>
<span class="line"><span>  你在外面看，地球在里面</span></span>
<span class="line"><span>  经纬线画在球面上，描述地球表面的位置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>天球：</span></span>
<span class="line"><span>  你在里面看，天球在外面</span></span>
<span class="line"><span>  黄道·天赤道画在球面上，描述天体的方向</span></span></code></pre></div><p>两者的逻辑完全一样，只是视角反了。</p><hr><h3 id="回到你的原问题" tabindex="-1">回到你的原问题 <a class="header-anchor" href="#回到你的原问题" aria-label="Permalink to &quot;回到你的原问题&quot;">​</a></h3><blockquote><p>&quot;地球绕太阳公转的轨道平面，投影到天球上的大圆&quot;</p></blockquote><p>现在可以完整理解这句话了：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一步：地球绕太阳公转，有一个轨道平面（真实存在的平面）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二步：把这个平面&quot;无限延伸&quot;，</span></span>
<span class="line"><span>        让它与天球（假想球面）相交</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三步：相交出来的那个大圆，就是黄道</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第四步：太阳在一年中，沿着黄道走一圈（360°）</span></span>
<span class="line"><span>        每走15°，就是一个节气</span></span></code></pre></div><p><strong>&quot;投影到天球&quot;这个表述，本质上就是：</strong><br> 把三维空间中的真实轨道平面，<br> 转化为天球球面上的一条线（大圆），<br> 方便用角度坐标来描述太阳的位置。</p><h3 id="顺带解释几个常见的-天球类-表述" tabindex="-1">顺带解释几个常见的&quot;天球类&quot;表述 <a class="header-anchor" href="#顺带解释几个常见的-天球类-表述" aria-label="Permalink to &quot;顺带解释几个常见的&quot;天球类&quot;表述&quot;">​</a></h3><p>读古籍和天文资料时，这些词会频繁出现：</p><table tabindex="0"><thead><tr><th style="text-align:left;">表述</th><th style="text-align:left;">意思</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;太阳在黄道上运行&quot;</td><td style="text-align:left;">从地球看，太阳沿黄道（天球大圆）移动</td></tr><tr><td style="text-align:left;">&quot;黄经285°&quot;</td><td style="text-align:left;">太阳在黄道上距春分点285°的位置</td></tr><tr><td style="text-align:left;">&quot;春分点&quot;</td><td style="text-align:left;">黄道与天赤道的交点之一（黄经0°）</td></tr><tr><td style="text-align:left;">&quot;太阳过春分点&quot;</td><td style="text-align:left;">太阳运行到黄经0°的时刻，即春分节气</td></tr><tr><td style="text-align:left;">&quot;北天极附近的星&quot;</td><td style="text-align:left;">天球北极点附近的星，即拱极星</td></tr><tr><td style="text-align:left;">&quot;天球日周运动&quot;</td><td style="text-align:left;">地球自转导致所有天体每天绕北天极转一圈的视运动</td></tr><tr><td style="text-align:left;">&quot;岁差使春分点西移&quot;</td><td style="text-align:left;">春分点在黄道上缓慢向西漂移（每年约50角秒）</td></tr></tbody></table><p><strong>一句话总结：</strong></p><blockquote><p>天球是一个&quot;假想的无限大球面&quot;，以观测者为中心。<br> 它不是真实存在的物体，而是一套<strong>描述天体方向的坐标工具</strong>。<br> 所有&quot;投影到天球&quot;的表述，本质上都是：<br><strong>把三维空间中的真实位置，转化为球面上的角度坐标。</strong></p></blockquote><p>搞懂天球，黄道·黄经·天赤道·春分点这一串词，就全部串起来了。</p>`,171)])])}const u=a(l,[["render",p]]);export{h as __pageData,u as default};
